export type GeoPoint = readonly [title: string, description: string];
type ThreePoints = readonly [GeoPoint, GeoPoint, GeoPoint];
type SixPoints = readonly [GeoPoint, GeoPoint, GeoPoint, GeoPoint, GeoPoint, GeoPoint];

export interface GeoOverlapContent {
  subject: string;
  headingSubject: string;
  tagline: string;
  intro: string;
  workflow: string;
  checks: ThreePoints;
  cards: SixPoints;
  closing: string;
  capabilitiesIntro: string;
  cta: string;
}

const conciseHeadings: Record<string, string> = {
  'Digital Transformation': 'Digital Workflows',
  'Salesforce Implementation': 'Salesforce CRM Services',
  'IT Staff Augmentation': 'IT Team Support',
  'Cybersecurity Consulting': 'Cyber Security Consulting',
  'Software Modernization': 'Legacy Software Renewal',
  'Transportation Management': 'Transport Management',
};

function page(subject: string, tagline: string, intro: string, workflow: string, checks: ThreePoints, cards: SixPoints): GeoOverlapContent {
  return {
    subject, headingSubject: conciseHeadings[subject] ?? subject, tagline, intro, workflow, checks, cards,
    closing: `Define how ${checks.map(([title]) => title.toLowerCase()).join(', ')} connect to the people and systems responsible for ${subject}.`,
    capabilitiesIntro: `Plan ${cards.map(([title]) => title.toLowerCase()).join(', ')} as connected parts of the ${subject} scope.`,
    cta: `Discuss ${subject}`,
  };
}

